document.querySelectorAll('.filter button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let n=0;document.querySelectorAll('.event').forEach(x=>{let show=b.dataset.filter==='all'||x.dataset.kind===b.dataset.filter||(b.dataset.filter==='use'&&x.dataset.kind==='earlier');x.hidden=!show;if(show)n++});document.getElementById('timeline-count').textContent=n+' dated entries shown'}));
